    // 将多个长篇小说解析为一本书
    u.combineNovels = function(novels) {
        if (!util.settings.COMBINE_NOVELS) return novels
        return novels.filter(novel => {
            // 单本直接解析为一本书
            if (!novel.seriesId) {
                return true
            }
            // 集合中没有该系列解析为一本书
            if (!seriesSet.has(novel.seriesId)) {
                seriesSet.add(novel.seriesId)
                return true
            }
            return false
        })
    }

    // 屏蔽作者
