    // 小说信息格式化
    u.formatNovels = function(novels) {
        novels = util.novelFilter(novels)
        novels.forEach(novel => {
            novel.title = novel.title.trim()
            if (!novel.userName.startsWith("@")) novel.userName = `@${novel.userName}`
            novel.coverUrl = urlCoverUrl(novel.coverUrl)
            novel.readingTime = `${novel.readingTime / 60} 分钟`
            novel.createDate = dateFormat(novel.createDate)
            novel.updateDate = dateFormat(novel.updateDate)

            novel.tagsList = []
            for (let i in novel.tags) {
                let tag = novel.tags[i]
                if (tag.includes("/")) {
                    let tags = tag.split("/")
                    novel.tagsList = novel.tagsList.concat(tags)
                } else {
                    novel.tagsList.push(tag)
                }
            }
            novel.tags = Array.from(new Set(novel.tagsList))
            novel.tags = novel.tags.map(item => `#${item}`)
            novel.tags = novel.tags.join(",")

            let collectMsg
            if (novel.seriesId) {
                collectMsg = `📃 追更：${util.checkStatus(novel.isWatched)}追更系列`
            } else {
                collectMsg = `❤️ 收藏：${util.checkStatus(novel.isBookmark)}加入收藏`
            }

            if (util.settings.MORE_INFORMATION) {
                novel.description = `\n🅿️ 登录：${util.checkStatus(isLogin())}登录账号
                ${collectMsg}\n📖 书名：${novel.title}\n👤 作者：${novel.userName}
                #️ 标签：${novel.tags}\n⬆️ 上传：${novel.createDate}
                🔄 更新：${novel.updateDate}\n📄 简介：${novel.description}`
            } else {
                novel.description = `\n🅿️ 登录：${util.checkStatus(isLogin())}登录账号
                ${collectMsg}\n⬆️ 上传：${novel.createDate}\n🔄 更新：${novel.updateDate}
                📄 简介：${novel.description}`
            }
        })
        novels = util.novelFilter2(novels)
        return novels
    }

    u.getUserNovelsById = function(resp) {
        let novels = [], seriesIds = []
        // 获取系列小说，与 util.handNovels 系列详情兼容
        if (resp.body.novelSeries.length >= 1) {
            resp.body.novelSeries.forEach(novel =>{
                seriesIds.push(novel.id)
                novel.textCount = novel.publishedTotalCharacterCount
                novel.description = novel.caption
            })
            novels = novels.concat(resp.body.novelSeries)
        }

        // 获取所有系列内部的小说 ID
        let seriesNovelIds = []
        if (util.environment.IS_LEGADO) {
            let seriesUrls = seriesIds.map(seriesId => urlIP(urlSeriesNovelsTitles(seriesId)))
            // let resp = getAjaxAllJson(seriesUrls).map(resp => resp.body)
            // seriesNovelIds = resp.flat().map(item => item.id)
            seriesNovelIds = getAjaxAllJson(seriesUrls).flatMap(resp => resp.body.map(item => item.id))
        }

        if (util.environment.IS_SOURCEREAD) {
            seriesIds.forEach(seriesId => {
                let novels = getAjaxJson(urlIP(urlSeriesNovelsTitles(seriesId))).body
                seriesNovelIds.push.apply(seriesNovelIds, novels.map(novel => novel.id))
            })
        }
        // java.log(`有系列的小说ID：${JSON.stringify(seriesNovelIds)}`)
        // java.log(JSON.stringify(seriesNovelIds.length))

        // 获取单篇小说，默认过滤系列小说的 novelId，否则与系列重复
        let novelIds = Object.keys(resp.body.novels)
        novelIds = novelIds.filter(novelId => (!seriesNovelIds.includes(novelId)))
        // java.log(`真单篇的小说ID：${JSON.stringify(novelIds)}`)
        // java.log(JSON.stringify(novelIds.length))

        if (novelIds) {
            let singles = getAjaxJson(urlIP(urlNovelsDetailed(getFromCache("pixivUid"), novelIds))).body
            novels = novels.concat(Object.values(singles).reverse())
        }
        return novels
    }


    // 正文，目录，详情，搜索：从网址获取id，返回单篇小说 res，系列返回首篇小说 res
    // pixiv 默认分享信息中有#号，不会被识别成链接，无法使用添加网址
    u.getNovelRespFirst = function(result) {
        let novelId = 0, res = {"body": {}}
        let isJson = isJsonString(result)
        let isHtml = isHtmlString(result)

        if (!isJson && isHtml) {
            let id = baseUrl.match(new RegExp("\\d+"))[0]
            let pattern = "(https?://)?(www\\.)?pixiv\\.net(/ajax)?/users?/\\d+"
            let isAuthor = baseUrl.match(new RegExp(pattern))
            if (isAuthor) {
                java.log(`作者ID：${id}`)
                novelId = Object.keys(getAjaxJson(urlIP(urlUserWorkLatest(id))).body.novels).reverse()[0]
            }

            pattern = "(https?://)?(www\\.)?pixiv\\.net/novel/series/\\d+"
            let isSeries = baseUrl.match(new RegExp(pattern))
            if (isSeries) {
                java.log(`系列ID：${id}`)
                novelId = getAjaxJson(urlIP(urlSeriesNovels(id, 30, 0))).body.thumbnails.novel[0].id
            } else {
                let pattern = "(https?://)?(www\\.)?pixiv\\.net/novel/(show\\.php\\?id=)?\\d+"
                let isNovel = baseUrl.match(new RegExp(pattern))
                if (isNovel) {
                    novelId = id
                }
            }
        }
        if (isJson) {
            res = JSON.parse(result)
        }

        if (novelId) {
            java.log(`匹配小说ID：${novelId}`)
            res = getAjaxJson(urlIP(urlNovelDetailed(novelId)))
        }
        if (res.error === true) {
            java.log(`无法从 Pixiv 获取当前小说`)
            java.log(JSON.stringify(res))
        }
        return res
    }

    u.init(); u.logSource(); u.logEnvironment(); u.logSettings()
    util = u; java.put("util", objStringify(u))
